*/
    #process {
        background: var(--main-background-color) !important;
    }
    #process .dot_tp {
        background-color: var(--main-background-color) !important;
        border: 3px solid var(--block-background-color) !important;
    }
    #process .line {
        background: var(--block-background-color) !important;
    }
    #process .dot_bt {
        background-color: var(--main-background-color) !important;
        border: 3px solid var(--block-background-color) !important;
