      -moz-transition: -moz-transform .2s;
      transition: transform .2s;
      -webkit-transform-origin: 50% 0;
      -moz-transform-origin: 50% 0;
      transform-origin: 50% 0; }
  #rocket:hover {
    background-position: 50% -62px; }
    #rocket:hover i {
